(function(){const qr=document.getElementById("gh-mobile-qr");if(qr&&window.qrcode){const code=window.qrcode(0,"M");code.addData(qr.dataset.url);code.make();qr.innerHTML=code.createSvgTag({cellSize:6,margin:0,scalable:true,alt:qr.dataset.label,title:qr.dataset.label})}const copy=document.getElementById("gh-mobile-copy");if(copy){copy.addEventListener("click",()=>{const done=()=>{const label=copy.textContent;copy.textContent=copy.dataset.copied;setTimeout(()=>{copy.textContent=label},1800)};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(copy.dataset.url).then(done);return}const field=document.createElement("input");field.value=copy.dataset.url;document.body.appendChild(field);field.select();document.execCommand("copy");field.remove();done()})}})();